-- (1) 国試: blueprint_code で突き合わせる。
UPDATE quiz_question AS q SET category = v.category
FROM _kokushi AS v
WHERE q.exam_type = 'KOKUSHI' AND q.blueprint_code = v.blueprint_code
  AND q.category IS DISTINCT FROM v.category;

-- (2a) CBT: 選択肢の並びの md5 で突き合わせる。
CREATE TEMP TABLE _cbt_fp ON COMMIT DROP AS
SELECT q.id, (SELECT md5(string_agg(e->>'key' || ':' || (e->>'text'), '|' ORDER BY ord))
         FROM jsonb_array_elements(q.choices::jsonb) WITH ORDINALITY AS t(e, ord)) AS h
FROM quiz_question AS q WHERE q.exam_type = 'CBT';

UPDATE quiz_question AS q SET category = v.category
FROM _cbt_fp AS f JOIN _cbt_choices AS v ON v.h = f.h
WHERE q.id = f.id AND q.category IS DISTINCT FROM v.category;

-- (2b) CBT: 取り込み後に選択肢を直した行のために、選択肢で当たらなかった
-- ものは本文の md5 で引く。
UPDATE quiz_question AS q SET category = v.category
FROM _cbt_fp AS f, _cbt_text AS v
WHERE q.id = f.id
  AND NOT EXISTS (SELECT 1 FROM _cbt_choices AS c WHERE c.h = f.h)
  AND md5(q.question_text) = v.h
  AND q.category IS DISTINCT FROM v.category;

-- (3) seed_demo の見本（本文の md5）。科目名でないときだけ直す。
UPDATE quiz_question AS q SET category = v.category
FROM (VALUES
    ('CBT', '3c254ccb0b2ad3bc33f3eb546061d76b', '循環器'),
    ('CBT', '43dfd70637ff85ef696f2f2a472a6289', '循環器'),
    ('KOKUSHI', 'f1b63d9ccd299dcf080d65fc133467c9', '循環器'),
    ('CBT', 'f5266913c1b778677a36a1b2411c632a', '呼吸器'),
    ('CBT', '0539b7874f1548389ef58b6c59a19be9', '呼吸器'),
    ('KOKUSHI', '785c882c60074a8714d0da336c7bff94', '呼吸器'),
    ('CBT', 'bcbd58d2576cbdb5d3d978d7dda74eb7', '消化器'),
    ('CBT', 'e182d7a6c3cd698c0a0a1c20bd3eb0b3', '消化器'),
    ('KOKUSHI', '73acb0bb4d0b58fff0b7821f21ecf658', '肝・胆・膵'),
    ('CBT', 'd59f511c8fcede7a024e8c118f85d3a5', '内分泌・代謝'),
    ('CBT', 'bafbd97611ac8dbbca919135ca9d57da', '内分泌・代謝'),
    ('KOKUSHI', '3c8fd12bcaec1ea84da1644d85029711', '代謝・内分泌'),
    ('CBT', '91d3b32a643ca15b1cb857abf8b14dc8', '神経'),
    ('CBT', 'f2d55070076b7eab44c2e8f16112daaf', '神経'),
    ('KOKUSHI', 'ca95d821c343e544db75d7f378ffd82e', '神経')
) AS v(exam_type, h, category)
WHERE q.exam_type = v.exam_type AND md5(q.question_text) = v.h
  AND ((q.exam_type = 'KOKUSHI' AND q.category NOT IN ('循環器', '消化管', '肝・胆・膵', '代謝・内分泌', '呼吸器', '腎臓', '泌尿器', '神経', '血液', '免疫・膠原病', '感染症', '皮膚科', '整形外科', '眼科', '耳鼻咽喉科', '精神科', '小児科', '婦人科・乳腺外科', '産科', '救急・中毒', '麻酔', '放射線', '医学総論', '公衆衛生'))
    OR (q.exam_type = 'CBT' AND q.category NOT IN ('循環器', '消化器', '内分泌・代謝', '呼吸器', '腎臓', '泌尿器', '神経', '血液', '免疫・膠原病', '感染症', '腫瘍', '基礎医学', '皮膚', '運動器', '眼', '耳鼻咽喉', '精神', '小児（成長と発達）', '産婦人科', '救急・中毒・麻酔', '放射線', '医学総論・公衆衛生・診療の基本')));

-- 結果。4つの区分を1つの表にまとめる。
--   0.単問にした  … 四連問からほどいた設問の数
--   1.移した      … 何を何へ移したか（件数）
--   2.残った      … 正規名でないまま残った分野。0行なら完了
--   3.演習の一覧  … 演習画面に出る並び（公開中の設問）。記号は画面と同じ
WITH moved AS (
    SELECT b.exam_type, b.category AS before, q.category AS after, count(*) AS n
    FROM _before AS b JOIN quiz_question AS q ON q.id = b.id
    WHERE q.category <> b.category
    GROUP BY 1, 2, 3
),
leftover AS (
    SELECT exam_type, category, count(*) AS n FROM quiz_question
    WHERE (exam_type = 'KOKUSHI' AND category NOT IN ('循環器', '消化管', '肝・胆・膵', '代謝・内分泌', '呼吸器', '腎臓', '泌尿器', '神経', '血液', '免疫・膠原病', '感染症', '皮膚科', '整形外科', '眼科', '耳鼻咽喉科', '精神科', '小児科', '婦人科・乳腺外科', '産科', '救急・中毒', '麻酔', '放射線', '医学総論', '公衆衛生'))
       OR (exam_type = 'CBT' AND category NOT IN ('循環器', '消化器', '内分泌・代謝', '呼吸器', '腎臓', '泌尿器', '神経', '血液', '免疫・膠原病', '感染症', '腫瘍', '基礎医学', '皮膚', '運動器', '眼', '耳鼻咽喉', '精神', '小児（成長と発達）', '産婦人科', '救急・中毒・麻酔', '放射線', '医学総論・公衆衛生・診療の基本'))
    GROUP BY 1, 2
),
canon_order AS (
    SELECT * FROM (VALUES
    ('CBT', '循環器', '0', '0'),
    ('CBT', '消化器', '0', '1'),
    ('CBT', '内分泌・代謝', '0', '2'),
    ('CBT', '呼吸器', '0', '3'),
    ('CBT', '腎臓', '0', '4'),
    ('CBT', '泌尿器', '0', '5'),
    ('CBT', '神経', '0', '6'),
    ('CBT', '血液', '0', '7'),
    ('CBT', '免疫・膠原病', '0', '8'),
    ('CBT', '感染症', '0', '9'),
    ('CBT', '腫瘍', '1', '10'),
    ('CBT', '基礎医学', '1', '11'),
    ('CBT', '皮膚', '1', '12'),
    ('CBT', '運動器', '1', '13'),
    ('CBT', '眼', '1', '14'),
    ('CBT', '耳鼻咽喉', '1', '15'),
    ('CBT', '精神', '1', '16'),
    ('CBT', '小児（成長と発達）', '1', '17'),
    ('CBT', '産婦人科', '1', '18'),
    ('CBT', '救急・中毒・麻酔', '1', '19'),
    ('CBT', '放射線', '1', '20'),
    ('CBT', '医学総論・公衆衛生・診療の基本', '1', '21'),
    ('KOKUSHI', '循環器', '0', '0'),
    ('KOKUSHI', '消化管', '0', '1'),
    ('KOKUSHI', '肝・胆・膵', '0', '2'),
    ('KOKUSHI', '代謝・内分泌', '0', '3'),
    ('KOKUSHI', '呼吸器', '0', '4'),
    ('KOKUSHI', '腎臓', '0', '5'),
    ('KOKUSHI', '泌尿器', '0', '6'),
    ('KOKUSHI', '神経', '0', '7'),
    ('KOKUSHI', '血液', '0', '8'),
    ('KOKUSHI', '免疫・膠原病', '0', '9'),
    ('KOKUSHI', '感染症', '0', '10'),
    ('KOKUSHI', '皮膚科', '1', '11'),
    ('KOKUSHI', '整形外科', '1', '12'),
    ('KOKUSHI', '眼科', '1', '13'),
    ('KOKUSHI', '耳鼻咽喉科', '1', '14'),
    ('KOKUSHI', '精神科', '1', '15'),
    ('KOKUSHI', '小児科', '1', '16'),
    ('KOKUSHI', '婦人科・乳腺外科', '1', '17'),
    ('KOKUSHI', '産科', '1', '18'),
    ('KOKUSHI', '救急・中毒', '1', '19'),
    ('KOKUSHI', '麻酔', '1', '20'),
    ('KOKUSHI', '放射線', '1', '21'),
    ('KOKUSHI', '医学総論', '1', '22'),
    ('KOKUSHI', '公衆衛生', '1', '23')
    ) AS v(exam_type, category, grp, pos)
),
listing AS (
    SELECT q.exam_type, q.category, count(*) AS n,
           coalesce(o.grp::int, 2) AS grp, coalesce(o.pos::int, 999) AS pos
    FROM quiz_question AS q
    LEFT JOIN canon_order AS o ON o.exam_type = q.exam_type AND o.category = q.category
    WHERE q.status = 'published' AND q.visibility = 'public'
    GROUP BY 1, 2, 4, 5
)
SELECT 区分, 試験, 記号, 分野, 問題数 FROM (
    SELECT '0.単問にした' AS 区分, exam_type AS 試験, '' AS 記号,
           '四連問の設問' AS 分野, count(*) AS 問題数, 0 AS k, 0 AS r
    FROM _series GROUP BY exam_type
    UNION ALL
    SELECT '1.移した', exam_type, '', before || ' → ' || after, n, 1, 0
    FROM moved
    UNION ALL
    SELECT '2.残った', exam_type, '', category, n, 2, 0 FROM leftover
    UNION ALL
    SELECT '3.演習の一覧', exam_type,
           chr(64 + row_number() OVER (PARTITION BY exam_type
                                       ORDER BY grp, pos, category COLLATE "C")::int),
           category || CASE WHEN grp = 2 THEN '（正規名でない）' ELSE '' END, n,
           3, row_number() OVER (PARTITION BY exam_type ORDER BY grp, pos, category COLLATE "C")
    FROM listing
) AS report
ORDER BY k, 試験, r, 分野;

COMMIT;
